//! OMEN Hub RS — a simple replacement for the OMEN Gaming Hub controls:
//! modes (with an automatic mode), fans, keyboard lighting, startup options.
//!
//! The hardware work runs in `omen_core::Controller` threads; this crate is
//! only the window, the notification-area icon and the settings.

mod instance;
mod tray;
mod ui;

use std::sync::{Arc, Mutex};
use std::time::Duration;

use omen_core::{Command, Config, Controller, Mode, OmenKeyAction};

pub const APP_TITLE: &str = "OMEN Hub RS";

pub fn log_line(msg: &str) {
    omen_core::log_line(msg);
}

/// Logo pixels (RGBA, generated by `assets/make_logo.py`).
pub(crate) const LOGO_64: &[u8] = include_bytes!("../../../assets/icon-64.rgba");
pub(crate) const LOGO_256: &[u8] = include_bytes!("../../../assets/icon-256.rgba");

/// The window is hidden in the notification area.
static HIDDEN: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// Hides the window to the notification area and gives unused memory back.
pub(crate) fn hide_main_window(ctx: &egui::Context) {
    ctx.send_viewport_cmd(egui::ViewportCommand::Visible(false));
    HIDDEN.store(true, std::sync::atomic::Ordering::Relaxed);
    trim_memory();
}

/// Returns the pages the process is not using to Windows (they come back on
/// demand). Most of them belong to the graphics driver and are only needed
/// while the window is shown.
pub(crate) fn trim_memory() {
    use windows::Win32::System::Threading::{GetCurrentProcess, SetProcessWorkingSetSize};
    unsafe {
        let _ = SetProcessWorkingSetSize(GetCurrentProcess(), usize::MAX, usize::MAX);
    }
}

pub(crate) fn show_main_window(ctx: &egui::Context) {
    HIDDEN.store(false, std::sync::atomic::Ordering::Relaxed);
    ctx.send_viewport_cmd(egui::ViewportCommand::Visible(true));
    ctx.send_viewport_cmd(egui::ViewportCommand::Minimized(false));
    ctx.send_viewport_cmd(egui::ViewportCommand::Focus);
    instance::show_window(APP_TITLE);
    ctx.request_repaint();
}

/// Saves, returns fan control to the BIOS when needed, and exits.
pub(crate) fn quit(controller: &Controller, config: &Arc<Mutex<Config>>) -> ! {
    config.lock().unwrap_or_else(|e| e.into_inner()).save();
    controller.shutdown();
    log_line("omen-hub: quit");
    std::process::exit(0);
}

#[cfg(windows)]
pub(crate) fn relaunch_elevated() {
    use windows::core::HSTRING;
    use windows::Win32::UI::Shell::ShellExecuteW;
    use windows::Win32::UI::WindowsAndMessaging::SW_SHOWNORMAL;
    unsafe {
        if let Ok(exe) = std::env::current_exe() {
            ShellExecuteW(
                None,
                &HSTRING::from("runas"),
                &HSTRING::from(exe.to_string_lossy().to_string()),
                None,
                None,
                SW_SHOWNORMAL,
            );
        }
    }
}

/// Listens for the OMEN key (BIOS WMI event `hpqBEvnt` 29 / 8613) and runs the
/// action chosen in the settings.
fn spawn_omen_key_listener(ctx: egui::Context, controller: Arc<Controller>, config: Arc<Mutex<Config>>) {
    let spawned = std::thread::Builder::new().name("omen-key".into()).spawn(move || {
        let mut before_max = Mode::Auto;
        let mut logged_error = false;
        loop {
            let events = match omen_wmi::BiosEvents::subscribe() {
                Ok(e) => {
                    log_line("omen-key: listening");
                    logged_error = false;
                    e
                }
                Err(e) => {
                    if !logged_error {
                        log_line(&format!("omen-key: subscribe failed: {e}"));
                        logged_error = true;
                    }
                    std::thread::sleep(Duration::from_secs(30));
                    continue;
                }
            };
            loop {
                match events.next(1000) {
                    Ok(Some(ev)) if ev.is_omen_key() => {
                        let (action, mode) = {
                            let c = config.lock().unwrap_or_else(|e| e.into_inner());
                            (c.omen_key, c.mode)
                        };
                        log_line(&format!("omen-key: pressed -> {action:?}"));
                        let new_mode = match action {
                            OmenKeyAction::OpenApp => {
                                show_main_window(&ctx);
                                None
                            }
                            OmenKeyAction::NextMode => {
                                let i = Mode::MAIN.iter().position(|m| *m == mode).map(|i| i + 1).unwrap_or(0);
                                Some(Mode::MAIN[i % Mode::MAIN.len()])
                            }
                            OmenKeyAction::ToggleMax if mode == Mode::Max => Some(before_max),
                            OmenKeyAction::ToggleMax => {
                                before_max = mode;
                                Some(Mode::Max)
                            }
                            OmenKeyAction::Nothing => None,
                        };
                        if let Some(m) = new_mode {
                            controller.send(Command::SetMode(m));
                            let mut c = config.lock().unwrap_or_else(|e| e.into_inner());
                            c.mode = m;
                            c.save();
                            ctx.request_repaint();
                        }
                    }
                    Ok(Some(ev)) => log_line(&format!("omen-key: other BIOS event {ev:?}")),
                    Ok(None) => {}
                    Err(e) => {
                        log_line(&format!("omen-key: event wait failed: {e}"));
                        std::thread::sleep(Duration::from_secs(5));
                        break;
                    }
                }
            }
        }
    });
    if let Err(e) = spawned {
        log_line(&format!("omen-key: thread failed: {e}"));
    }
}

pub fn run() -> Result<(), eframe::Error> {
    std::panic::set_hook(Box::new(|info| log_line(&format!("PANIC: {info}"))));

    let Some(_guard) = instance::acquire() else {
        log_line("omen-hub: already running, asked it to show");
        return Ok(());
    };
    log_line("omen-hub: starting");

    // Process COM security must be set before winit/OLE does it: the WMI
    // provider needs impersonation level (see docs/bios-wmi-commands.md).
    unsafe {
        use windows::Win32::System::Com::{
            CoInitializeEx, CoInitializeSecurity, COINIT_APARTMENTTHREADED, EOAC_NONE,
            RPC_C_AUTHN_LEVEL_DEFAULT, RPC_C_IMP_LEVEL_IMPERSONATE,
        };
        let _ = CoInitializeEx(None, COINIT_APARTMENTTHREADED);
        let _ = CoInitializeSecurity(
            None,
            -1,
            None,
            None,
            RPC_C_AUTHN_LEVEL_DEFAULT,
            RPC_C_IMP_LEVEL_IMPERSONATE,
            None,
            EOAC_NONE,
            None,
        );
    }

    let config = Config::load();
    let start_hidden = std::env::args().any(|a| a == "--tray") || config.start_minimized;

    let icon = egui::IconData {
        rgba: LOGO_64.to_vec(),
        width: 64,
        height: 64,
    };
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_title(APP_TITLE)
            .with_inner_size([1000.0, 720.0])
            .with_min_inner_size([820.0, 600.0])
            .with_visible(!start_hidden)
            .with_icon(icon),
        // OpenGL: ~110 MB instead of ~430 MB with the wgpu/DirectX 12 renderer.
        renderer: eframe::Renderer::Glow,
        ..Default::default()
    };

    eframe::run_native(
        APP_TITLE,
        options,
        Box::new(move |cc| {
            let controller = Arc::new(Controller::start(config.clone()));
            let config = Arc::new(Mutex::new(config));
            {
                let ctx = cc.egui_ctx.clone();
                instance::listen(move || show_main_window(&ctx));
            }
            spawn_omen_key_listener(cc.egui_ctx.clone(), controller.clone(), config.clone());
            // Keep the window state fresh even when nothing is clicked.
            {
                let ctx = cc.egui_ctx.clone();
                // Hidden: refresh every 5 s (tray tooltip) and trim every minute.
                std::thread::spawn(move || {
                    let mut tick = 0u32;
                    loop {
                        std::thread::sleep(Duration::from_millis(1000));
                        tick = tick.wrapping_add(1);
                        if !HIDDEN.load(std::sync::atomic::Ordering::Relaxed) {
                            ctx.request_repaint();
                        } else if tick.is_multiple_of(5) {
                            ctx.request_repaint();
                            if tick.is_multiple_of(60) {
                                trim_memory();
                            }
                        }
                    }
                });
            }
            Ok(Box::new(ui::App::new(cc, controller, config, start_hidden)))
        }),
    )
}
